    when it acts as a vowel: i.e., when it sits between two consonants
    (as in "rhythms"), but not at the end of a word (as in "sky").
    """
    vowels = set("aeiou")
    lowered = text.lower()

    def is_consonant(ch):
        return ch.isalpha() and ch not in vowels

    count = 0
    for i, ch in enumerate(lowered):
        if ch in vowels:
            count += 1
        elif ch == "y" and 0 < i < len(lowered) - 1:
            if is_consonant(lowered[i - 1]) and is_consonant(lowered[i + 1]):
                count += 1
    return count
